216	        assert.ok(readFileSync(file).equals(beforeBytes), '保存失败后 ideas.json 被改动');
217	        if (blocker.tmpExpectation === 'absent') {
218	          assert.equal(existsSync(tmpFile), false, '失败后不应留下临时文件');
219	        } else {
