236	        assert.equal(afterRecoverList.status, 200);
237	        assert.deepEqual(afterRecoverList.data.ideas, seeded);
238	        assert.ok(readFileSync(file).equals(beforeBytes), '仅恢复写入能力后 ideas.json 被改动');
239	
240	        // 重新提交刚才那条合法意见：按已有功能 201 并返回完整保存结果。
241	        const retried = await postIdea(server, NEW_IDEA);
242	        assert.equal(retried.status, 201);
243	        assert.ok(isCompleteSavedIdea(retried.data.idea));
244	        const savedIdea = retried.data.idea as Idea;
245	        assert.equal(savedIdea.title, NEW_IDEA.title);
246	        assert.equal(savedIdea.description, NEW_IDEA.description);
247	        assert.equal(savedIdea.scenario, NEW_IDEA.scenario);
248	        for (const old of seeded) {
