252	        // 列表只多出这一条：新意见在最前，旧记录保持原来的相对顺序与内容。
253	        const afterSuccess = await getIdeas(server);
254	        assert.equal(afterSuccess.status, 200);
255	        assert.equal(afterSuccess.data.ideas.length, seeded.length + 1);
256	        assert.deepEqual(afterSuccess.data.ideas[0], savedIdea);
257	        assert.deepEqual(afterSuccess.data.ideas.slice(1), seeded);
