316	        const listed = await getIdeas(server);
317	        assert.equal(listed.status, 200);
318	        assert.equal(listed.data.ideas.length, 1);
319	        assert.deepEqual(listed.data.ideas[0], retried.data.idea);
320	      } finally {
321	        restoreBlocker(blocker, dir, tmpFile);
