cd /tmp && rm -rf cleanup-check && mkdir cleanup-check && cd cleanup-check && node --input-type=module -e "
import { lstatSync, readFileSync, renameSync, unlinkSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';

// 与 server.ts 中 saveIdeas 完全相同的逻辑
const dataFile = '/tmp/cleanup-check/ideas.json';
function saveIdeas(records) {
  const tempFile = dataFile + '.tmp';
  writeFileSync(tempFile, JSON.stringify(records, null, 2) + '\n');
  try {
    renameSync(tempFile, dataFile);
  } catch (error) {
    try {
      if (lstatSync(tempFile).isFile()) unlinkSync(tempFile);
    } catch {}
    throw error;
  }
}

writeFileSync(dataFile, '[]\n');
// 制造 rename 失败：把正式文件换成目录（rename 文件到目录失败），临时文件可删
const before = readFileSync(dataFile);
// 直接模拟：先删掉正式文件并放目录
import { rmSync } from 'node:fs';
rmSync(dataFile);
mkdirSync(dataFile);
try {
  saveIdeas([{id:'x'}]);
  console.log('ERROR: should have thrown');
} catch (e) {
  console.log('threw:', e.code);
}
console.log('tmp exists after failure:', existsSync(dataFile + '.tmp'));
console.log('dataFile still directory:', lstatSync(dataFile).isDirectory());
rmSync(dataFile, {recursive:true});
"

